// MIT. Complete native extraction through the original MySQL source lifetime.
import { datasetExtractionOptions } from '../../postgres/publisher/stream.mjs';
import { quoteIdentifier } from '../declaration.mjs';
import { mysqlCall } from '../lifecycle.mjs';

export class MysqlDatasetError extends Error {
  constructor(code) { super(code); this.name = 'MysqlDatasetError'; this.code = code; }
}
const fail = code => new MysqlDatasetError(code);

/** Keep the original publisher's row, byte, deadline and ordering contract. */
export function mysqlDatasetExtractionOptions(query, supplied = {}) {
  try { return datasetExtractionOptions(query, supplied); }
  catch (issue) {
    throw fail(/^DATASET_[A-Z0-9_]+$/.test(issue?.code ?? '') ? issue.code : 'DATASET_EXTRACTION_OPTIONS_INVALID');
  }
}

function statement(query, limits) {
  const names = query.columns.map(quoteIdentifier);
  let flag = '__sf30_export_oversized';
  while (query.columns.includes(flag)) flag += '_';
  const order = limits.order.map(item => {
    const name = quoteIdentifier(item.column);
    return name + ' IS NULL ASC, ' + name + ' ' + item.direction.toUpperCase();
  }).join(', ');
  const size = names.map(name => 'COALESCE(OCTET_LENGTH(' + name + '),0)').join(' + ');
  const source = 'SELECT ' + names.join(', ') + '\nFROM (\n' + query.sql +
    '\n) AS sf30_mysql_approved\nORDER BY ' + order + '\nLIMIT ' + (limits.maxRows + 1);
  // LIMIT prevents merging this derived table. Oversized values are suppressed
  // inside MySQL, and the outer ordering preserves the reviewed null-last order.
  return 'SELECT ' + names.map(name => 'IF((' + size + ') > ' + limits.maxRowBytes + ',NULL,' + name + ') AS ' + name).join(', ') +
    ', ((' + size + ') > ' + limits.maxRowBytes + ') AS ' + quoteIdentifier(flag) +
    '\nFROM (\n' + source + '\n) AS sf30_mysql_extract\nORDER BY ' + order;
}

/** The source opens WITH CONSISTENT SNAPSHOT, READ ONLY before this operation,
 * and commits only after every awaited row consumer and this stream complete. */
export async function readMysqlDataset(connection, query, { name, values, options,
  onRow, ensureActive, serverVersion, metadata, encodeScalar }) {
  const maria = serverVersion.toLowerCase().includes('mariadb');
  const info = await mysqlCall(connection, 'query', 'SELECT CONNECTION_ID(), UTC_TIMESTAMP(6), @@session.' +
    (maria ? 'tx_isolation' : 'transaction_isolation'));
  ensureActive();
  const [connectionId, startedAt, isolation] = info.rows[0] ?? [];
  if (String(isolation).replaceAll('-', ' ').toUpperCase() !== 'REPEATABLE READ')
    throw fail('DATASET_EXTRACTION_TRANSACTION_INVALID');

  const command = connection.execute({ sql: statement(query, options), rowsAsArray: true }, values);
  // The native stream removes its listeners when a consumer throws. Keep a
  // command error receiver through the source's subsequent socket retirement.
  command.on('error', () => {});
  const rows = command.stream({ highWaterMark: 1 });
  let columnTypes, rowCount = 0, sourceBytes = 0;
  const fields = actual => {
    try {
      ensureActive();
      if (actual.length !== query.columns.length + 1 ||
          actual.slice(0, -1).some((field, index) => field.name !== query.columns[index]))
        throw fail('QUERY_PROJECTION_CHANGED');
      columnTypes = metadata(actual.slice(0, -1));
    } catch (issue) { rows.destroy(issue); }
  };
  rows.once('fields', fields);
  try {
    for await (const row of rows) {
      ensureActive();
      if (rowCount >= options.maxRows) throw fail('DATASET_EXTRACTION_TOO_MANY_ROWS');
      if (!columnTypes || !Array.isArray(row) || row.length !== query.columns.length + 1 || Number(row.at(-1)) !== 0)
        throw fail('DATASET_EXTRACTION_ROW_TOO_LARGE');
      const selected = row.slice(0, -1);
      sourceBytes += selected.reduce((total, value) => total + (value === null ? 0 :
        Buffer.isBuffer(value) ? value.length : Buffer.byteLength(String(value))), 0);
      if (sourceBytes > options.maxBytes) throw fail('DATASET_EXTRACTION_TOO_MANY_BYTES');
      const result = Object.fromEntries(query.columns.map((column, index) => [column, encodeScalar(selected[index])]));
      await onRow(result, columnTypes, { rowCount: rowCount + 1, sourceBytes });
      ensureActive(); rowCount++;
    }
    ensureActive();
    if (!columnTypes) throw fail('QUERY_PROJECTION_CHANGED');
  } finally { rows.removeListener('fields', fields); rows.destroy(); }
  return { schema: 'stellar-forge.mysql-dataset-extraction.v1', query: name,
    rowCount, sourceBytes, columns: [...query.columns], columnTypes,
    transaction: { connectionId: String(connectionId), startedAt: String(startedAt),
      serverVersion, isolation: 'REPEATABLE READ', readOnly: true,
      consistentSnapshotRequested: true, scope: 'single-native-extraction' },
    valueEncoding: 'mysql-exact-scalars', binaryEncoding: 'base64-object', nullEncoding: 'json-null',
    order: options.order, nullOrder: 'last' };
}

// MIT. OData editions use the existing dataset seller and SF82 release lifecycle.
import { mkdir, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { loadDatasetConfig } from '../dataset-handler.mjs';
import { openDatasetVersions, DATASET_SNAPSHOT_PARAMETER } from '../dataset-refresh/versions.mjs';
import { DATASET_BINDING_SCHEMA, datasetContractSha256, prepareDatasetRelease, readDatasetSourceFiles } from '../../sf82-seller-pilot/release-dataset.mjs';
import { initReleaseStore, readReleaseState, stageRelease, releaseStatus, activateRelease, rollbackRelease, runActiveRelease } from '../../sf82-seller-pilot/releases.mjs';
import { digest, formatted, writeNew, identifier, fault } from './state.mjs';

export async function openODataPublisher({ workspace }) {
  const directory=join(workspace.directory,'publisher'),releases=join(directory,'releases');
  await mkdir(directory,{recursive:true,mode:0o700});
  try{await readReleaseState(releases);}catch(error){if(error.code!=='ENOENT')throw error;await initReleaseStore(releases);}
  async function prepare({exportId,releaseId,label,runtime={port:0}}){
    identifier(exportId);identifier(releaseId,'release ID');
    const record=(await workspace.state()).exports.find(value=>value.id===exportId);
    if(!record?.merchant)throw fault('ODATA_MERCHANT_EXPORT','Export this edition with public payment terms and origin first.');
    const sourceDirectory=join(workspace.directory,'exports',exportId),packageDirectory=join(directory,'packages',exportId);
    const datasetDirectory=join(directory,'datasets',exportId);
    await mkdir(packageDirectory,{recursive:true,mode:0o700});
    const dataset=await loadDatasetConfig(join(sourceDirectory,'dataset.json')),description=dataset.describe();
    const seller=JSON.parse(await readFile(join(sourceDirectory,'seller.json'),'utf8'));
    if(!seller.routes[0].definition.queryParameters.some(value=>value.name==='snapshot'))
      seller.routes[0].definition.queryParameters.push(DATASET_SNAPSHOT_PARAMETER);
    const source=await readFile(join(sourceDirectory,'source.json'));
    const binding={schema:DATASET_BINDING_SCHEMA,datasetDirectory,contractSha256:datasetContractSha256(description),
      baselineSnapshot:description.snapshot,sourceSha256:digest(source)};
    const files={'dataset.csv':await readFile(join(sourceDirectory,'dataset.csv')),'dataset.json':await readFile(join(sourceDirectory,'dataset.json')),
      'source.json':source,'seller.json':formatted(seller),'binding.json':formatted(binding)};
    const sourceFiles=await readDatasetSourceFiles(sourceDirectory,JSON.parse(source));
    for(const file of sourceFiles)files[file.path]=await readFile(join(sourceDirectory,file.path));
    for(const [name,body]of Object.entries(files)){
      await mkdir(join(packageDirectory,name,'..'),{recursive:true,mode:0o700});
      try{await writeNew(join(packageDirectory,name),body);}catch(error){if(error.code!=='EEXIST')throw error;
        if(digest(await readFile(join(packageDirectory,name)))!==digest(body))throw fault('ODATA_PACKAGE_CHANGED','A retained merchant package differs.',409);}
    }
    let initialConfig;
    try{await readFile(join(datasetDirectory,'state.json'));}catch(error){
      if(error.code!=='ENOENT')throw error;initialConfig=join(packageDirectory,'dataset.json');
    }
    const versions=await openDatasetVersions({directory:datasetDirectory,...(initialConfig?{initialConfig}:{})});
    try{if(versions.describe().snapshot!==description.snapshot)throw fault('ODATA_VERSION_CHANGED','The retained dataset version differs from this edition.',409);}finally{await versions.close();}
    const prepared=await prepareDatasetRelease(packageDirectory);
    const staged=await stageRelease(releases,{id:releaseId,label:label||description.name,datasetPackage:packageDirectory,runtime});
    return {exportId,releaseId,packageDirectory,datasetDirectory,dataset:prepared.description,staged};
  }
  return {directory,releases,prepare,status:()=>releaseStatus(releases),
    activate:({id,expectedGeneration,reason})=>activateRelease(releases,identifier(id),{expectedGeneration,reason}),
    rollback:({to,expectedGeneration,reason})=>rollbackRelease(releases,{to,expectedGeneration,reason}),
    run:options=>runActiveRelease(releases,options)};
}

// MIT. Slack delivery for the original SF93 incident queue.
import {request as httpsRequest} from 'node:https';
import {createHash} from 'node:crypto';

const API = 'https://slack.com/api/';
const identities = new Map();
const digest = value => createHash('sha256').update(value).digest('hex');
export const slackTeamId = /^T[A-Z0-9]{8,31}$/;
export const slackChannelId = /^[CGD][A-Z0-9]{8,31}$/;
export const slackTimestamp = /^[1-9][0-9]{8,15}\.[0-9]{1,6}$/;
const actorId = /^[UW][A-Z0-9]{8,31}$/;
const transient = new Set(['ratelimited','rate_limited','internal_error','fatal_error',
  'service_unavailable','request_timeout','org_login_required','team_added_to_org']);

/** Resolve the selected workspace/channel, keeping the token only in memory. */
export function resolveSlackDestination(config, environment) {
  const token = environment[config.tokenEnv];
  if (typeof token !== 'string' || token.length < 16 || token.length > 4096 || /[^\x21-\x7e]/.test(token))
    return {reason:'SLACK_TOKEN_UNAVAILABLE'};
  if (!slackTeamId.test(config.teamId) || !slackChannelId.test(config.channelId))
    return {reason:'SLACK_DESTINATION_INVALID'};
  const endpointHash = digest(JSON.stringify([API,config.teamId,config.channelId]));
  return {transport:'slack',token,teamId:config.teamId,channelId:config.channelId,
    binding:{id:config.id,transport:'slack',tokenEnv:config.tokenEnv,
      teamId:config.teamId,channelId:config.channelId,endpointHash}};
}

const labels = {ENDPOINT_UNAVAILABLE:'Merchant endpoint unavailable',OBSERVER_INCOMPLETE:'Merchant observations incomplete',
  HTTP_5XX:'Merchant server errors',DISCONNECTED:'Merchant connections interrupted',
  DELIVERY_UNAVAILABLE:'Delivery observations unavailable',DELIVERY_BACKLOG:'Merchant delivery backlog',
  DELIVERY_EXHAUSTED:'Merchant delivery attempts exhausted'};
const transitions = {OPENED:'Opened',ACKNOWLEDGED:'Acknowledged',RECOVERED:'Recovered',RETIRED:'Registration retired',REMINDER:'Operator reminder'};
const countLabels = {requests:'Requests',failures:'Failures',percent:'Failure percentage',minimum:'Minimum count',
  thresholdPercent:'Threshold percentage',pending:'Pending deliveries',exhausted:'Exhausted deliveries',
  oldestPendingSeconds:'Oldest pending delivery (seconds)',thresholdSeconds:'Age threshold (seconds)',
  observerErrors:'Observer errors',consecutivePolls:'Consecutive observations',windowMinutes:'Observation window (minutes)'};

/** Format only the original allowlisted notification fields. */
export function slackMessage(event, destination) {
  const p = JSON.parse(event.body);
  const lines = [
    `${transitions[p.transition]}: ${labels[p.kind]}`,
    `Merchant: ${p.merchantId}`,
    `Incident: ${p.incidentId}`,
    `State: ${p.status}`,
    `Observed: ${p.occurredAt}`,
    `Opened: ${p.openedAt}`,
  ];
  for (const [name,label] of Object.entries(countLabels))
    if (Object.hasOwn(p.counts,name)) lines.push(`${label}: ${p.counts[name]}`);
  if (p.sessionId) lines.push(`Source session: ${p.sessionId}`);
  lines.push('',p.status === 'OPEN'
    ? 'Acknowledge this incident in the merchant support controls and continue its original recovery.'
    : p.status === 'ACKNOWLEDGED'
      ? 'Operator acknowledgment is recorded. Recovery continues in the original merchant support controls.'
      : p.status === 'RECOVERED'
        ? 'The original watcher observed recovery. Its before and after captures are available in merchant support.'
        : 'Review the original registration change in merchant support.',
    `Event: ${p.eventId}`);
  const body = {channel:destination.channelId,text:lines.join('\n'),mrkdwn:false,
    parse:'none',unfurl_links:false,unfurl_media:false,reply_broadcast:false,
    client_msg_id:event.id};
