      maxRowBytes:maxProjectedRowBytes,maxBytes:128*1024*1024,maxRowLimit:2097152},
      outputs:Object.fromEntries([...output].map(([name,record])=>[name,{bytes:record.bytes,sha256:record.hash.digest('hex')}]))};
