        references.some(value => !Object.hasOwn(query.parameters, value.name)))
      throw new TypeError('MSSQL_PARAMETERS_MUST_MATCH_DECLARATION');
    for (const spec of Object.values(query.parameters)) parameterSqlType(spec);
