    quoteIdentifier(flag) + '\nFROM (\n' + projectedStatement(query) + '\n) AS sf30_mssql_page\nORDER BY ' +
    query.orderBy.map(item=>'sf30_mssql_page.'+quoteIdentifier(item.column)+' '+item.direction).join(',');
}

