    BigInt(payment.amount) <= (1n << 127n) - 1n &&
    typeof payment.asset === 'string' && payment.asset.length > 0 && payment.asset.length <= 128 &&
    typeof payment.payTo === 'string' && payment.payTo.length > 0 && payment.payTo.length <= 128 &&
