    'DATASET_ARCHIVE_NATIVE_PAGE_CHANGED');
  if(retained.stoppedPage)for(const key of ['index','intentId'])
    need(actual.stoppedPage?.[key]===retained.stoppedPage[key],
      'DATASET_ARCHIVE_ORIGINAL_RECONCILIATION_CHANGED');
