      availabilityDirectory: value.availabilityDirectory ?? null,
      ...(value.python ? { python: value.python } : {}),
      ...(value.jsonrpc ? { jsonrpc: value.jsonrpc } : {}),
      ...(value.upstreams ? { upstreams: value.upstreams } : {}) },
    facilitator: value.facilitator,
